  (3, 'Brooklyn Paws Collective', 'Brooklyn', 'NY', '11201', 40.6943, -73.9903, '(718) 555-0199', 'team@brooklynpaws.org', 'https://example.org', 'Urban rescue focused on apartment-ready companions and first-time adopters.', 'demo-shelter-3', 1),
  (4, 'Garden State Greyhound & Hound', 'Princeton', 'NJ', '08540', 40.3573, -74.6672, '(609) 555-0133', 'info@gshound.org', 'https://example.org', 'Hounds of every shape — from retired racers to basset buddies.', 'demo-shelter-4', 1),
