INSERT INTO success_stories (user_id, dog_id, title, story, status, approved_by) VALUES
  (1, 1, 'Luna found her couch', 'We were nervous first-time adopters, but the matching quiz pointed us to a calm senior who fits our apartment perfectly. Six months later she runs the house.', 'approved', 2),
  (1, 2, 'From shelter to trail buddy', 'Ranger had so much energy the shelter struggled to keep up. Now he hikes with me every weekend and sleeps like a log every night.', 'approved', 2),
  (1, 3, 'Our kids'' best friend', 'The application was simple and the shelter answered every question in Messages. Biscuit has been glued to our kids since day one.', 'approved', 2),
  (1, 4, 'Second chances', 'Tank was overlooked for months. He''s the gentlest dog I''ve ever met.', 'pending', NULL);
